import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array to probabilistically determine 
    whether an item is present in a set. The design leverages two key parameters: 
    the expected number of items and the desired false positive rate. 
    The optimal bit array size and number of hash functions are computed from these parameters.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal number of bits
        self.size = self._optimal_bit_size()

        # Calculate optimal number of hash functions
        self.hash_count = self._optimal_hash_count()

        # Create a bit array initialized to 0
        self.bit_array = [0] * self.size

    def _optimal_bit_size(self) -> int:
        """Calculate optimal bit array size based on expected items and false positive rate."""
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_hash_count(self) -> int:
        """Calculate optimal number of hash functions based on bit array size and expected items."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate hash values for a given item using multiple hash functions."""
        return [int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.size for i in range(self.hash_count)]

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

